// Bundled media catalog for the Lifeguard-Pro.org Social Media Studio prototype.
//
// Images are original code-drawn SVG illustrations generated by `node scripts/generate-assets.mjs`
// (public/assets/posts/{id}-{portrait|square|story}.svg). Videos are silent motion graphics rendered by
// `node scripts/render-videos.mjs` (public/assets/video/*.webm + *.png posters). Video dimensions and
// durations below were measured from the rendered files in headless Chromium.
// None of these assets are photographs and none depict real people.

import type { TopicKey } from '../domain/types';

export type { TopicKey };

export interface SeedMedia {
  id: string;
  kind: 'image' | 'video';
  topic: TopicKey | 'any';
  /** The headline shown in the graphic. */
  title: string;
  /** Descriptive alt text. Always "Illustration" / "Motion graphic", never "photo". */
  alt: string;
  variants: { portrait: string; square: string; story: string } | null;
  src?: string;
  poster?: string;
  width: number;
  height: number;
  durationSec?: number;
  orientation: 'portrait' | 'landscape' | 'square';
}

const variants = (id: string) => ({
  portrait: `/assets/posts/${id}-portrait.svg`,
  square: `/assets/posts/${id}-square.svg`,
  story: `/assets/posts/${id}-story.svg`,
});

const image = (id: string, topic: TopicKey, title: string, alt: string): SeedMedia => ({
  id,
  kind: 'image',
  topic,
  title,
  alt,
  variants: variants(id),
  width: 1080,
  height: 1350,
  orientation: 'portrait',
});

